/* jkt-pp-faq-schema-builder */
try{
(function(){function b(){if(document.getElementById('jkt-pp-faq-schema'))return;var g=[];var h1=document.querySelector('h1');var nm=h1?h1.textContent.replace(/\s+/g,' ').trim():document.title.split('|')[0].trim();var url=location.origin.replace('justkeeps-travel.webflow.io','www.justkeepstravel.com')+location.pathname;if(!document.getElementById('jkt-pp-schema-2026-10-09'))g.push({'@type':'BreadcrumbList','@id':url+'#breadcrumb','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':'https://www.justkeepstravel.com/'},{'@type':'ListItem','position':2,'name':'Partners','item':'https://www.justkeepstravel.com/partners'},{'@type':'ListItem','position':3,'name':nm,'item':url}]});var r=document.querySelector('[data-jkt-pp-faq]');if(r){var q=[];r.querySelectorAll('h3').forEach(function(h){var p=h.nextElementSibling;if(p&&p.tagName==='P')q.push({'@type':'Question','name':h.textContent.trim(),'acceptedAnswer':{'@type':'Answer','text':p.textContent.trim()}})});if(q.length)g.push({'@type':'FAQPage','@id':url+'#faq','mainEntity':q})}if(!g.length)return;var s=document.createElement('script');s.type='application/ld+json';s.id='jkt-pp-faq-schema';s.textContent=JSON.stringify({'@context':'https://schema.org','@graph':g});document.head.appendChild(s)}if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',b);else b()})();
}catch(e){console.warn("jkt embed block failed: jkt-pp-faq-schema-builder",e)}
